/**
 * E-Document Format Utilities
 *
 * Shared utilities for working with e-document formats across the application.
 * Provides country flag mapping and format type display formatting.
 */

/**
 * Get country flag emoji for e-document format
 *
 * @param format - The e-document format string (e.g., "FATTURAPA", "UAE FTA VAT", "XRECHNUNG 3.0")
 * @returns The corresponding country flag emoji or empty string if no match
 */
export function getCountryFlag(format: string): string {
  if (!format) return '';

  const formatUpper = format.toUpperCase();

  // Country flag mapping based on format prefix/keywords
  const flagMap: Record<string, string> = {
    // Europe
    FATTURAPA: '\u{1F1EE}\u{1F1F9}', // Italy
    'E-SLOG': '\u{1F1F8}\u{1F1EE}', // Slovenia
    FACTURX: '\u{1F1EB}\u{1F1F7}', // France
    ZUGFERD: '\u{1F1E9}\u{1F1EA}', // Germany
    XRECHNUNG: '\u{1F1E9}\u{1F1EA}', // Germany
    PEPPOL: '\u{1F1EA}\u{1F1FA}', // EU
    TEAPPSXML: '\u{1F1EB}\u{1F1EE}', // Finland
    FINVOICE: '\u{1F1EB}\u{1F1EE}', // Finland
    KSEF: '\u{1F1F5}\u{1F1F1}', // Poland
    FACTURAE: '\u{1F1EA}\u{1F1F8}', // Spain
    EBINTERFACE: '\u{1F1E6}\u{1F1F9}', // Austria
    OIOUBL: '\u{1F1E9}\u{1F1F0}', // Denmark
    EHF: '\u{1F1F3}\u{1F1F4}', // Norway
    'SI-UBL': '\u{1F1F3}\u{1F1F1}', // Netherlands
    SVEFAKTURA: '\u{1F1F8}\u{1F1EA}', // Sweden

    // Middle East
    UAE: '\u{1F1E6}\u{1F1EA}', // UAE
    FTA: '\u{1F1E6}\u{1F1EA}', // UAE FTA VAT
    ZATCA: '\u{1F1F8}\u{1F1E6}', // Saudi Arabia
    FATOORA: '\u{1F1F8}\u{1F1E6}', // Saudi Arabia
    TURKEY: '\u{1F1F9}\u{1F1F7}', // Turkey

    // Asia Pacific
    INVOICENOW: '\u{1F1F8}\u{1F1EC}', // Singapore
    'JP PINT': '\u{1F1EF}\u{1F1F5}', // Japan
    JAPAN: '\u{1F1EF}\u{1F1F5}', // Japan
    KOREA: '\u{1F1F0}\u{1F1F7}', // Korea
    MYINVOIS: '\u{1F1F2}\u{1F1FE}', // Malaysia
    MALAYSIA: '\u{1F1F2}\u{1F1FE}', // Malaysia
    TAIWAN: '\u{1F1F9}\u{1F1FC}', // Taiwan
    THAILAND: '\u{1F1F9}\u{1F1ED}', // Thailand
    VIETNAM: '\u{1F1FB}\u{1F1F3}', // Vietnam
    INDONESIA: '\u{1F1EE}\u{1F1E9}', // Indonesia
    PHILIPPINES: '\u{1F1F5}\u{1F1ED}', // Philippines
    CHINA: '\u{1F1E8}\u{1F1F3}', // China
    INDIA: '\u{1F1EE}\u{1F1F3}', // India
    'PINT A-NZ': '\u{1F1E6}\u{1F1FA}', // Australia/New Zealand
    AUSTRALIA: '\u{1F1E6}\u{1F1FA}', // Australia
    KAZAKHSTAN: '\u{1F1F0}\u{1F1FF}', // Kazakhstan

    // Latin America
    PERU: '\u{1F1F5}\u{1F1EA}', // Peru
    CPE: '\u{1F1F5}\u{1F1EA}', // Peru CPE
    SUNAT: '\u{1F1F5}\u{1F1EA}', // Peru SUNAT
    BRAZIL: '\u{1F1E7}\u{1F1F7}', // Brazil
    NFE: '\u{1F1E7}\u{1F1F7}', // Brazil NFe
    ARGENTINA: '\u{1F1E6}\u{1F1F7}', // Argentina
    AFIP: '\u{1F1E6}\u{1F1F7}', // Argentina AFIP
    CHILE: '\u{1F1E8}\u{1F1F1}', // Chile
    DTE: '\u{1F1E8}\u{1F1F1}', // Chile DTE
    SII: '\u{1F1E8}\u{1F1F1}', // Chile SII
    COLOMBIA: '\u{1F1E8}\u{1F1F4}', // Colombia
    DIAN: '\u{1F1E8}\u{1F1F4}', // Colombia DIAN
    ECUADOR: '\u{1F1EA}\u{1F1E8}', // Ecuador
    URUGUAY: '\u{1F1FA}\u{1F1FE}', // Uruguay
    PARAGUAY: '\u{1F1F5}\u{1F1FE}', // Paraguay
    MEXICO: '\u{1F1F2}\u{1F1FD}', // Mexico
    CFDI: '\u{1F1F2}\u{1F1FD}', // Mexico CFDI
    SAT: '\u{1F1F2}\u{1F1FD}', // Mexico SAT
  };

  // Find matching flag by prefix/keyword
  for (const [keyword, flag] of Object.entries(flagMap)) {
    if (formatUpper.includes(keyword.toUpperCase())) {
      return flag;
    }
  }

  // Default: no flag for generic formats
  return '';
}

/**
 * Format e-document type for display with country flag
 *
 * @param method - The e-document classification method (e.g., "UAE FTA VAT", "FACTURX 1.07.2")
 * @returns Formatted string with country flag prefix (e.g., "🇦🇪 UAE FTA VAT") or just the method if no flag
 */
export function formatEDocType(method: string): string {
  if (!method) return '';
  const flag = getCountryFlag(method);
  return flag ? `${flag} ${method}` : method;
}

/**
 * Check if a document is an electronic document based on extraction method
 *
 * @param extractionMethod - The extraction method string
 * @returns True if the document is an electronic document
 */
export function isElectronicDocument(extractionMethod: string | undefined | null): boolean {
  return extractionMethod === 'ELECTRONIC_DOCUMENT';
}
